/**
 * The build outputs the SSR Pages Function runs, generated by `npm run
 * build` before Cloudflare Pages bundles functions/:
 * - build/ssr/index.js: React Router's server build (kept by
 *   scripts/vite/keepServerBuildPlugin.ts);
 * - build/ssr/inline-css.json: the stylesheets finalize.ts inlines into
 *   every page, by href (the same inlining for server-rendered pages).
 *
 * Imported lazily (pagesFunction.ts), so requests that never render (the
 * bridge's prefixes, the kill switch) don't evaluate the app. Not imported
 * by tests or the SPA.
 */
import type { ServerBuild } from "react-router"

import * as build from "../../build/ssr/index.js"
import inlineCss from "../../build/ssr/inline-css.json"

export const serverBuild = build as unknown as ServerBuild
export const inlineStylesheetsByHref = inlineCss as Record<string, string>
